import sys, json, copy
sys.path.insert(0,'/private/tmp/opensip-design-corrections/claude-attribution-capture-assessment.v1/tools')
import pc
K=pc.K; S=K.S
def semantic_full_run(graph):
    seed, objects, blobs, _ = S.seed_seal(graph)
    _, owner = K.IDENTITY.open_run_closure(seed, objects, blobs)
    i = graph['inputs']
    out = K.R.derive(i['planId'], i['executionPlanId'], i['evaluatorClosure'], i['evaluationInputRefs'], objects, blobs, owner)
    run, objects, blobs = S.seal_derived(graph, out, objects, blobs)
    result = K.R.replay(run, objects, blobs)
    closed = K.IDENTITY.close_run(run, objects, blobs)
    assert closed == result['runId']
    return result, out['proof']
res={}
for label, kw in [('declares-exists', dict(atom={'op':'exists','relation':'declares','minResolution':'syntactic','filters':[]})),
                  ('declares-exists-no-second-partition', dict(atom={'op':'exists','relation':'declares','minResolution':'syntactic','filters':[]}, second_partition=False))]:
    g=S.build_ts_semantic_graph(**kw)
    try:
        m,_=K.H.build_manifest(copy.deepcopy(g))
        views={}
        for v in g['viewIds']:
            vd=g['objects'][v][1]
            views[pc.short(v)]=[[g['objects'][s][1]['relation'], g['objects'][s][1]['resolution'], pc.short(g['objects'][s][1]['sourceUniverse'])] for s in vd['scopeIds']]
        cells=[[c['capabilityId'],c['languageMode'],[pc.short(b['universe']) for b in c['programBindings']]] for c in g['enumerationPlan']['cells']]
        adm=K.H.M.admit_execution_inputs(**K.H.admission_kwargs(copy.deepcopy(g)))
        entry={'cells':cells,'views':views,'rows':pc.rows(m),'admission':[adm.get('result'),adm.get('refusals')]}
        try:
            r,p=semantic_full_run(copy.deepcopy(g))
            entry['closedRun']={'verdict':r['verdict'],'runId':r['runId'],'exactManifest':p['executionInputsDigest']==K.M.raw_digest(m),'causes':sorted(d['cause'] for d in p['executionDeficiencies'])}
        except Exception as exc:
            entry['closedRun']={'exception':type(exc).__name__+':'+str(exc)[:500]}
    except Exception as exc:
        entry={'buildError':type(exc).__name__+':'+str(exc)[:500]}
    res[label]=entry
p=pc.RUNTIME/'receipts/semantic-declares-baseline.json'
if p.exists(): raise SystemExit('exists')
p.write_text(json.dumps(res,indent=2)+chr(10)); print(json.dumps(res,indent=1))
